(function(){'use strict';const T=THREE,host=document.querySelector('#canvas-host'),renderer=new T.WebGLRenderer({antialias:innerWidth>600,alpha:false,powerPreference:'default'});renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<600?1.25:1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;host.append(renderer.domElement);const scene=new T.Scene();scene.background=new T.Color(0xe9ede4);const camera=new T.PerspectiveCamera(32,1,.1,40),hemi=new T.HemisphereLight(0xfff4e8,0xadbbaa,1.7);scene.add(hemi);const sun=new T.DirectionalLight(0xffead4,3);sun.position.set(-3,5,5);sun.castShadow=true;sun.shadow.mapSize.set(512,512);sun.shadow.normalBias=.025;Object.assign(sun.shadow.camera,{left:-2,right:2,top:3,bottom:-1,near:.1,far:15});scene.add(sun);const fill=new T.DirectionalLight(0xc3def0,1.2);fill.position.set(4,3,-2);scene.add(fill);
const ground=new T.Mesh(new T.CylinderGeometry(1.25,1.31,.10,64),new T.MeshStandardMaterial({color:0xdce2d3,roughness:.94}));ground.position.y=-.04;ground.receiveShadow=true;scene.add(ground);const bench=new T.Group();scene.add(bench);function box(w,h,d,x,y,z){const m=new T.Mesh(new T.BoxGeometry(w,h,d),new T.MeshStandardMaterial({color:0x8d7355,roughness:.9}));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;bench.add(m);}box(.95,.07,.45,0,.95,-.10);box(.95,.48,.05,0,1.22,-.32);for(const x of[-.36,.36])for(const z of[-.24,.06])box(.06,.93,.06,x,.46,z);bench.visible=false;
const state={key:'p3',view:'front',motion:'idle',framing:'full',light:'day',outfit:'photo',compare:'new',ready:false},angles={front:0,quarter:Math.PI/4,side:Math.PI/2,back:Math.PI};let model=null,previous=null,yaw=0,phase=0,last=performance.now(),frames=0,disposed=false,epoch=0;const times=[];function resize(){const r=host.getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(host);resize();
function frame(){const head=state.framing==='head',compare=state.compare==='both',seated=state.motion==='sit';camera.position.set(0,head?1.82:seated?1.7:1.5,head?(compare?3.9:2.45):(compare?6.3:seated?5.8:5.0));camera.lookAt(0,head?1.58:seated?1.25:1.10,0);if(model)model.group.position.x=compare?.74:0;if(previous){previous.group.visible=compare;previous.group.position.x=-.74;}const labels=document.querySelector('.version-labels');labels.classList.toggle('single',!compare);document.querySelector('#before-label').hidden=!compare;}frame();
async function select(key){if(!['p3'].includes(key))return;const version=++epoch;state.ready=false;document.querySelector('#status').textContent='正在載入照片 '+key.slice(1)+' 的髮型與人物…';const r=await fetch('/api/preview/select',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({key})});if(!r.ok)throw Error('PREVIEW_UNAVAILABLE');await Promise.all([CozyPortraitHair.load(key),key==='p5'?Promise.resolve():CozyPortraitHairQ2.load(key)]);if(version!==epoch)return;model?.dispose();previous?.dispose();previous=CozyAvatarPortraitsQ2.create(scene,{portraitPreset:'photo-'+key+'-v1'});previous.setAppearance({avatarPreset:key==='p5'?'portrait-li-shuhuan-v1':'photo-'+key+'-v1',skin:'orange',hair:key==='p5'?'portrait-low-tie':'portrait',outfit:''});model=CozyAvatarPortraits.create(scene,{portraitPreset:'photo-'+key+'-v1'});model.setAppearance({avatarPreset:'photo-'+key+'-v1',skin:'orange',hair:'portrait',outfit:''});state.key=key;state.ready=true;control('outfit',state.outfit);bench.visible=state.motion==='sit';frame();for(const b of document.querySelectorAll('[data-person]'))b.setAttribute('aria-pressed',String(b.dataset.person===key));document.querySelector('#person-label').textContent=CozyPortraitConfig.get('photo-'+key+'-v1').label;document.querySelector('#before-label').textContent='前版 Q2';document.querySelector('#after-label').textContent='嘉玲 · B 開心露齒笑';document.querySelector('#status').textContent='同一鏡頭・相同顯示尺度・腳底基準';}
function control(type,value){if(type==='outfit'&&['photo','uniform'].includes(value)){state.outfit=value;model?.setAppearance({avatarPreset:'photo-'+state.key+'-v1',skin:'orange',hair:'portrait',outfit:value==='uniform'&&['p3','p5'].includes(state.key)?'staff-uniform':''});}else if(type==='compare'&&['both','new'].includes(value)){state.compare=value;frame();}else if(type==='view'&&value in angles){state.view=value;yaw=angles[value];}else if(type==='frame'&&['head','full'].includes(value)){state.framing=value;frame();}else if(type==='motion'&&['idle','walk','sit','wave'].includes(value)){state.motion=value;bench.visible=value==='sit';frame();}else if(type==='light'&&['day','dusk','night'].includes(value)){state.light=value;const config={day:[0xffead4,3,1.7,0xe9ede4],dusk:[0xffb36f,2.3,1.1,0xe6d9cf],night:[0xb8c9ed,.8,.75,0xcbd4d8]}[value];sun.color.setHex(config[0]);sun.intensity=config[1];hemi.intensity=config[2];scene.background.setHex(config[3]);}else return;for(const b of document.querySelectorAll('[data-'+type+']'))b.setAttribute('aria-pressed',String(b.dataset[type]===value));}
let pointer=null;renderer.domElement.addEventListener('pointerdown',e=>{pointer={id:e.pointerId,x:e.clientX};renderer.domElement.setPointerCapture(e.pointerId);});renderer.domElement.addEventListener('pointermove',e=>{if(!pointer||e.pointerId!==pointer.id)return;yaw+=(e.clientX-pointer.x)*.012;pointer.x=e.clientX;});renderer.domElement.addEventListener('pointerup',()=>pointer=null);renderer.domElement.addEventListener('pointercancel',()=>pointer=null);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.person)void select(b.dataset.person).catch(err=>document.querySelector('#status').textContent='載入未完成，請稍後重新整理。');for(const type of['outfit','compare','view','frame','motion','light'])if(b.dataset[type])control(type,b.dataset[type]);});
function tick(now){if(disposed)return;requestAnimationFrame(tick);const dt=Math.min(.1,(now-last)/1000);last=now;phase+=dt*6;model?.animate(phase,state.motion==='walk',state.motion==='sit',state.motion==='wave');previous?.animate(phase,state.motion==='walk',state.motion==='sit',state.motion==='wave');if(model)model.group.rotation.y=yaw;if(previous)previous.group.rotation.y=yaw;bench.rotation.y=yaw;renderer.render(scene,camera);frames++;if(dt>0&&frames>15){times.push(dt*1000);if(times.length>240)times.shift();}}requestAnimationFrame(tick);void select('p3').catch(e=>document.querySelector('#status').textContent='載入未完成，請重新整理。');
function metrics(){const sorted=[...times].sort((a,b)=>a-b);return{...state,frames,frameMsP50:sorted[Math.floor(sorted.length*.5)]||0,frameMsP95:sorted[Math.floor(sorted.length*.95)]||0,model:model?.state(),previous:previous?.state?.()||{type:'original-city-procedural'},proportions:model?{newHeight:new T.Box3().setFromObject(model.group).getSize(new T.Vector3()).y,oldHeight:new T.Box3().setFromObject(previous.group).getSize(new T.Vector3()).y,newSkullHeight:new T.Box3().setFromObject(model.head).getSize(new T.Vector3()).y}:null,geometry:renderer.info.memory.geometries,textures:renderer.info.memory.textures,drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,hair:CozyPortraitHair.stats()};}window.PhotoFourStudio=Object.freeze({select,control,metrics,get model(){return model;},dispose(){if(disposed)return;disposed=true;model?.dispose();previous?.dispose();CozyPortraitHair.dispose();CozyPortraitHairQ2.dispose();renderer.dispose();}});window.addEventListener('pagehide',()=>PhotoFourStudio.dispose(),{once:true});})();
